slides=json.loads((src/'slides.json').read_text(encoding='utf-8'))
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>Murdoku · 双版本美术设计稿</title><style>
*{box-sizing:border-box}body{margin:0;background:#101719;color:#e7ebe8;font-family:'Microsoft YaHei',sans-serif}header{padding:22px 32px;display:flex;align-items:center;gap:14px;flex-wrap:wrap}header strong{font-size:22px;margin-right:auto}button{cursor:pointer;font:inherit}header button,nav button{background:#263735;color:#fff;border:1px solid #53645d;border-radius:6px;padding:10px 18px}button.active{background:#cbb47c;color:#172721}nav{display:flex;gap:8px;padding:0 32px 18px;flex-wrap:wrap}.viewport{width:100%;overflow:auto;padding:0 20px}.screen{width:1600px;height:900px;position:relative;transform-origin:top left;background:var(--bg);color:var(--ink);overflow:hidden;border:1px solid var(--line)}.A{--bg:#f3ebdd;--ink:#203d36;--muted:#6c7367;--panel:#fffcf3;--accent:#99733c;--primary:#203d36;--on:#fff9eb;--line:#cabfa8;--soft:#e5ddcc;--good:#357b66;--bad:#ad4d46}.B{--bg:#142333;--ink:#e8eef0;--muted:#9eafb9;--panel:#263c4c;--accent:#73c5b4;--primary:#73c5b4;--on:#102d31;--line:#4a6172;--soft:#1b3041;--good:#8bd5ba;--bad:#f19986}.el{position:absolute}.label{letter-spacing:3px;text-transform:uppercase;font-size:15px;color:var(--accent)}.title{font-size:40px;letter-spacing:4px;font-weight:700}.muted{color:var(--muted)}.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;box-shadow:0 10px 28px #00000012}.btn{border:1px solid var(--line);border-radius:8px;background:var(--panel);color:var(--ink);font-size:24px;display:flex;align-items:center;justify-content:center;gap:12px}.btn.primary{background:var(--primary);color:var(--on);border-color:var(--primary)}.btn.disabled{opacity:.45}.frame{inset:18px;border:1px solid var(--line);pointer-events:none}.board{width:656px;height:656px;left:572px;top:102px}.clue{display:flex;gap:18px;align-items:center;padding:16px 20px}.avatar{width:48px;height:48px;background:var(--soft);border:1px solid var(--line);border-radius:50%;display:grid;place-items:center;font-size:23px;flex-shrink:0}.chip{padding:7px 13px;background:var(--soft);border-radius:4px;font-size:15px;display:inline-block}.annotation{font-size:14px;color:var(--muted)}.selected{outline:3px solid var(--accent);outline-offset:3px}.shade{inset:0;background:#08111ccc;display:grid;place-items:center}.modal{width:640px;padding:42px;text-align:center}.modal h2{font-size:34px;margin:12px}.modal p{line-height:1.9}.row{display:flex;gap:16px}.row .btn{padding:15px;flex:1}.spec{max-width:1250px;margin:26px auto 80px;padding:30px;background:#1c282b;border:1px solid #3b4c4d;line-height:1.9}.spec h2{color:#e8d9b0}.swatches{display:flex;gap:12px;flex-wrap:wrap}.swatch{width:145px;padding:16px;border:1px solid #62706e;border-radius:6px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #425054}small{display:block;color:#b9c4c4}.notice{padding:10px 32px;color:#dfc28f;font-size:14px}.scene-footer{left:60px;bottom:30px;font-size:14px;color:var(--muted)}
</style><header><strong>MURDOKU / 美术双方案</strong><button onclick="theme='A';render()" id="ta">A · 典藏案卷</button><button onclick="theme='B';render()" id="tb">B · 月下展馆</button></header><nav id="nav"></nav><div class="notice">独立设计预览 · 保留棋盘原 SVG · 背景插画生成失败，当前仅展示方案底色；背景构图规范见页面下方。</div><div class="viewport" id="vp"><main class="screen A" id="screen"></main></div><section class="spec" id="spec"></section><script>
const boards=BOARDS,slides=SLIDES;let theme='A',page='首页',step=0,group='l1',modal='确认';const pages=['首页','选关','关卡一','关卡二','教程','弹窗','组件状态'];const $=s=>document.querySelector(s);function el(x,y,w,h,cls,text){return `<div class="el ${cls}" style="left:${x}px;top:${y}px;width:${w}px;${h?'height:'+h+'px;':''}">${text}</div>`}function btn(x,y,w,h,text,primary=false,action=''){return `<button class="el btn ${primary?'primary':''}" style="left:${x}px;top:${y}px;width:${w}px;height:${h}px" ${action?`onclick="${action}"`:''}>${text}</button>`}function board(id){return `<img class="el board" src="${boards[id]}" alt="原项目棋盘 ${id}，未重新绘制">`}function level(two=false){let clues=two?['画廊助理在桌子旁边','有两人坐在椅子上','夜班门卫在书架旁边','随行记者在夜班门卫上方','只有随行记者在植物旁边','我独自一人']:['收藏家在第 5 列','旧识古董商在植物旁边','只有值班保安站在地毯上','夜班清洁工站在椅子上','前台姑娘在桌子旁边'];let s=btn(50,40,52,52,'‹',false,"page='选关';render()")+el(126,43,420,44,'label','案件 '+(two?'002 / 双影':'001 / 夜盗独行'))+el(62,142,440,55,'title',two?'双影':'夜盗独行')+el(62,205,400,36,'muted','调查用时  00:33  ·  '+(two?'留意线索的真假':'线索全部为真'))+board(two?'l2-1':'l1-1');clues.forEach((t,i)=>s+=el(62,264+i*(two?80:98),430,two?70:86,'panel clue '+(i===0?'selected':''),`<div class="avatar">${i===clues.length-1?'V':String.fromCharCode(65+i)}</div><div><div style="font-size:16px;color:var(--muted)">线索 ${i+1}</div><div style="font-size:18px;margin-top:7px">${t}</div></div>`));s+=btn(1310,160,220,64,'✓ 提交',true,"page='弹窗';modal='确认';render()")+btn(1310,254,220,64,'↻ 重置',false,"page='弹窗';modal='重置';render()")+btn(1310,348,220,64,'↶ 撤销')+el(1310,486,220,42,'label','摆位进度')+el(1310,530,220,70,'title',two?'0 / 6':'0 / 5')+btn(1310,650,220,64,'⌕ 提示')+el(600,790,650,40,'muted','轻点写笔记　·　长按正式放置　·　家具及棋盘原样保留');return s}
function render(){ $('#ta').className=theme==='A'?'active':'';$('#tb').className=theme==='B'?'active':'';$('#nav').innerHTML=pages.map(p=>`<button class="${p===page?'active':''}" onclick="page='${p}';render()">${p}</button>`).join('');let s='<div class="el frame"></div>';if(page==='首页'){s+=el(384,104,833,30,'label','MURDOKU / '+(theme==='A'?'典藏案卷':'月下展馆'))+el(384,145,833,110,'title','侦探推理 · 摆位谜题');['选关','从存档点开始','商城','背包'].forEach((t,i)=>s+=btn(608,300+i*100,383,73,t,i===0,i<2?"page='"+(i===0?'选关':'关卡一')+"';render()":"modal='未开放';page='弹窗';render()"));s+=el(595,727,420,40,'muted','让每一条线索，找到它的位置。')}else if(page==='选关'){s+=btn(50,40,52,52,'‹',false,"page='首页';render()")+el(384,67,833,75,'title','选择关卡');['夜盗独行','双影','案件 003','案件 004'].forEach((t,i)=>{let x=208.33+i*277.5;s+=el(x,275,232.5,324,'panel '+(i===0?'selected':''),`<div style="padding:22px"><div class="label">CASE / 00${i+1}</div><h2>${t}</h2>${i<2?`<img src="${boards[i?'l2-1':'l1-1']}" style="width:150px;height:150px" alt="原棋盘缩略图">`:'<div style="height:150px;display:grid;place-items:center;color:var(--muted)">内容占位</div>'}<div class="chip">${i<2?(i?'6 × 6 · 6 人':'5 × 5 · 5 人'):'关名以正式数据为准'}</div></div>`);if(i<2)s+=btn(x,620,232.5,52,'开始调查',i===0,`page='关卡${i?'二':'一'}';render()`)});s+=btn(50,424,52,52,'‹')+btn(1498,424,52,52,'›')+el(745,793,200,58,'muted','第 1 / 1 页')}else if(page==='关卡一'||page==='关卡二'){s+=level(page==='关卡二')}else if(page==='教程'){let a=slides[group];step=Math.min(step,a.length-1);let cur=a[step];s+=el(40,100,510,700,'panel',`<div style="padding:28px"><div class="label">调查手册 / ${group==='home'?'基础':group==='l1'?'第一关':'第二关'}</div><h1 style="font-size:32px">操作与推理</h1><div class="row">${['home','l1','l2'].map((g,i)=>`<button onclick="group='${g}';step=0;render()">${['基础','第一关','第二关'][i]}</button>`).join('')}</div><p class="muted">第 ${step+1} / ${a.length} 步</p><div style="height:6px;background:var(--soft)"><div style="height:6px;background:var(--accent);width:${(step+1)/a.length*100}%"></div></div><h2 style="margin-top:40px">${cur.title}</h2><p style="font-size:23px;line-height:1.85">${cur.caption}</p><span class="chip">步骤序号 + 图形强调，不只靠颜色</span></div>`)+board(cur.id)+btn(64,714,210,58,'上一步',false,'step=Math.max(0,step-1);render()')+btn(300,714,210,58,'下一步',true,`step=Math.min(${a.length-1},step+1);render()`)+btn(1310,160,220,64,'退出教程',false,"page='关卡一';render()");}else if(page==='弹窗'){s+=level(false)+`<div class="el shade"><div class="panel modal"><div class="label">${modal==='成功'?'CASE CLOSED':'调查提示'}</div><h2>${({确认:'提交当前推理？',重置:'重新开始本案？',成功:'案件已归档',失败:'摆位还没成立',未开放:'敬请期待'})[modal]}</h2><p>${({确认:'请确认已完成摆位，再继续指认。',重置:'将清空本关当前摆位与笔记。',成功:'完整线索已串联，继续调查下一个案件。',失败:'请重新检查每行每列与线索条件。这里不揭示假话或答案。',未开放:'商城与背包保留原入口，当前仅展示提示。'})[modal]}</p><div class="row"><button class="btn" onclick="page='关卡一';render()">返回调查</button><button class="btn primary" onclick="page='关卡一';render()">${modal==='重置'?'确认重置':'继续'}</button></div><p class="annotation">设计演示，不执行存档或游戏操作</p></div></div>`+el(80,815,1440,50,'row',['确认','重置','成功','失败','未开放'].map(t=>`<button onclick="modal='${t}';render()">${t}</button>`).join(''));}else{s+=el(80,70,1200,60,'title','组件与状态');['默认','悬停 / 焦点','按下','禁用','已完成','危险操作'].forEach((t,i)=>{s+=el(80+(i%3)*490,190+Math.floor(i/3)*230,430,170,'panel '+(i===1?'selected':''),`<div style="padding:25px"><div class="label">${t}</div><div class="btn ${i===2?'primary':''} ${i===3?'disabled':''}" style="margin-top:20px;padding:20px;${i===5?'border-color:var(--bad);color:var(--bad)':''}">${i===4?'✓ 已归档':i===5?'重置调查':'继续调查'}</div></div>`)});s+=el(80,720,1400,70,'muted','选中：描边＋标记　/　完成：对勾＋文字　/　错误：警示符号＋文字　/　禁用：降低强调但保留可读性')}s+=el(60,860,1400,24,'annotation',(theme==='A'?'A · 典藏案卷':'B · 月下展馆')+'　|　布局设计预览 · 背景插画待生成 · 未修改存档');$('#screen').className='screen '+theme;$('#screen').innerHTML=s;spec();resize()}
function spec(){const a=theme==='A';let colors=a?['#F3EBDD','#203D36','#FFFCF3','#99733C','#357B66','#AD4D46']:['#142333','#E8EEF0','#263C4C','#73C5B4','#8BD5BA','#F19986'];$('#spec').innerHTML=`<h2>${a?'A · 典藏案卷':'B · 月下展馆'}</h2><p>${a?'以博物馆的档案纸、墨绿封套和黄铜书签建立温暖、可信的调查氛围。标题像案卷封面，线索像独立口供卡，成功反馈像完成归档。':'以夜间展馆的蓝色空间、月白标签与青绿导视建立安静、理性的调查氛围。标题和卡片像展品铭牌，操作层清晰浮在深色背景上。'}</p><div class="swatches">${colors.map((c,i)=>`<div class="swatch" style="border-top:20px solid ${c}">${['背景','正文','面板','强调','成功','警示'][i]}<br>${c}</div>`).join('')}</div><h2>背景图设计</h2><p>${a?'主体是档案室两侧的墨绿柜体与黄铜拱形线饰，左下角小型台灯、右下角植物剪影。中央 75% 保持暖纸白低对比，不放道具、字符或复杂纹理。':'主体是月下展馆两侧拱廊与磨砂玻璃隔断，顶部侧角月光窗，底部两角低矮展台。中央 75% 保持平静深蓝，禁止星点、霓虹和密集纹理。'}</p><table><tr><th>页面</th><th>背景与界面关系</th></tr><tr><td>首页</td><td>完整背景，边缘装饰最丰富；四键及标题区域维持安静，标题下不得出现强光斑。</td></tr><tr><td>选关</td><td>背景装饰减半，卡片底面不透明；四张卡一行，左右箭头及页码始终保留。</td></tr><tr><td>关卡</td><td>沿用同一背景主体，降低边缘对比；棋盘周围留 24px 以上视觉隔离，原棋盘不调色、不加滤镜。</td></tr><tr><td>教程</td><td>背景进一步退后，讲解面板不透明；只在当前步骤使用强调色，棋盘使用原教程图。</td></tr><tr><td>弹窗</td><td>全屏深色遮罩约 80%，中央 640px 面板；仅保留一个主操作，危险操作增加明确文字。</td></tr></table><h2>图形、文字与状态</h2><p>1600×900 参考画布；标题 32–40px、正文 18–24px、辅助文字 14–16px。中文使用系统黑体，正式项目沿用引擎可用字体。按钮圆角 8px、卡片 12px；图标使用简洁几何轮廓，最小线宽 2px。悬停和选中增加外描边，按下提高填充对比，禁用降低强调。成功与错误都同时给图形和文字，不用红绿颜色作为唯一判断。</p><h2>棋盘与内容保留范围</h2><p>直接引用仓内教程 SVG，保留底板、格子、房间色、墙门、家具和教程标记。第一关 5×5、第二关 6×6。现有教程数据为基础 3 页、第一关 8 页、第二关 4 页，预览可逐页切换。部分旧教程文案可能与后续规则说明存在差异，本稿原样展示既有教学数据，不重新编写答案或规则。</p><h2>插件落地边界</h2><p>art-pipeline 允许矩形 100001、椭圆 100002、三角 100003、圆角板 107102、柔光圆 106056，颜色格式为 0xAARRGGBB。背景需拆成少量可复用的基础图形层；图片生成稿只是视觉目标，不能承诺整张直接导入。建议背景 20–40 层、单按钮 3–5 层、卡片 4–8 层作为设计预算，实际性能需后续测量。此插件主要处理家具模板，整屏 UI 还需结合控件工具；design-to-scene 面向 3D，本次 2D UI 不需要强行走 3D 场景。</p><p>后续若选定方案：先制作 ArtSpec 与预览、验证白名单和引用，再在独立新存档中验证文字尺寸、点击层与层级。视觉层和命中层保持分离，不更改现有交互语义。本次没有调用写档或嵌脚本阶段。</p><h2>依据与限制</h2><p>已核对四仓 remote：qianxing-murdoku、qianxing-murdoku-pro、qianxing-murdoku-project、qianxing-murdoku-tool。选关依据源码 PER=4、CARD_W=279、CARD_H=388.8，设计坐标按 5/6 转为预览坐标；已与本机整合源码核对这些常量一致。编辑器可覆盖卡片实际几何，本稿未读取当前运行存档，故保留基本布局，不宣称与实机逐像素一致。关卡棋盘基准来自插件 FRAME=(608,138,584)，教程 SVG 外围图幅 656×656。</p><p><b>背景生成状态：</b>两个方案均尝试两次，图片服务暂时出错，未生成独立背景 PNG；本网页仅展示底色和背景设计规范，不能视为完整背景插画交付。</p>`}function resize(){let scale=Math.min(1,(innerWidth-40)/1600);$('#screen').style.transform=`scale(${scale})`;$('#vp').style.height=900*scale+'px'}window.onresize=resize;render();</script></html>'''
html=html.replace('BOARDS',json.dumps(boards,ensure_ascii=False)).replace('SLIDES',json.dumps(slides,ensure_ascii=False))
(root/'Murdoku_两版美术设计稿.html').write_text(html,encoding='utf-8')
print('已生成双方案网页，内嵌棋盘数量',len(boards),'教程页数',sum(map(len,slides.values())))
